const clamp=(n,a=0,b=1)=>Math.max(a,Math.min(b,n));
const escape=text=>String(text??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>`pw-${globalThis.crypto?.randomUUID?.()||Math.random().toString(36).slice(2)}`;
const seedRandom=seed=>()=>{seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};
const svgNode=(name,attributes={})=>{const node=document.createElementNS('http://www.w3.org/2000/svg',name);for(const[key,value]of Object.entries(attributes))node.setAttribute(key,String(value));return node;};
const baseCSS=`:host{display:block;box-sizing:border-box;color:var(--pw-ink,#ece9e3);font:14px/1.5 system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;--bg:#16191c;--panel:#202427;--line:#353b3e;--muted:#9ca7ab;--ink:#ece9e3;--accent:#c6e6b0;--pad:20px;--radius:var(--pw-radius,16px);color-scheme:dark;isolation:isolate}:host([theme=light]){--bg:#f9f8f5;--panel:#fff;--line:#dedfd8;--muted:#626b66;--ink:#26332c;color:var(--ink);color-scheme:light}:host([density=compact]){--pad:12px}*,*::before,*::after{box-sizing:border-box}button,input,select,textarea{font:inherit}button{cursor:pointer;color:inherit}button:disabled{opacity:.45;cursor:not-allowed}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,[tabindex]:focus-visible{outline:2px solid var(--accent);outline-offset:4px}button{touch-action:manipulation}h1,h2,h3,p{margin:0}a{color:inherit}button,input,select,textarea{border-radius:8px}input,select,textarea{background:var(--bg);border:1px solid var(--line);color:var(--ink);padding:11px 12px;min-width:0}input::placeholder{color:var(--muted)}input[type=checkbox]{accent-color:var(--accent);width:17px;height:17px}button.primary{background:var(--accent);color:#172117;border:1px solid var(--accent);padding:11px 16px;font-weight:650}button.secondary{background:var(--panel);border:1px solid var(--line);padding:10px 14px}.label{font-size:10px;font-weight:650;letter-spacing:1.8px;text-transform:uppercase;color:var(--muted)}.panel{background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);padding:var(--pad)}.hint{font-size:12px;line-height:1.7;color:var(--muted)}.row{display:flex;align-items:center;gap:12px}.between{justify-content:space-between}.stack{display:flex;flex-direction:column;gap:16px}.accent{color:var(--accent)}:host([reduced]) *{animation:none!important;transition:none!important}:host([paused]) *{animation-play-state:paused!important}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap}.empty{padding:28px;text-align:center;color:var(--muted)}kbd{border:1px solid var(--line);border-radius:5px;padding:2px 6px;font:11px ui-monospace,monospace;color:var(--muted)}dialog{background:var(--panel);color:var(--ink);border:1px solid var(--line);border-radius:18px;max-width:calc(100vw - 32px);max-height:85dvh;padding:0;box-shadow:0 30px 120px #0008}dialog::backdrop{background:#05080aaa;backdrop-filter:blur(5px)}dialog header{padding:18px 22px;border-bottom:1px solid var(--line)}dialog .close{background:none;border:0;font-size:23px;color:var(--muted);padding:5px 8px}button.icon{background:none;border:1px solid var(--line);min-width:38px;height:38px;display:grid;place-items:center}::selection{background:#8da97355}@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition:none!important;scroll-behavior:auto!important}}@media(max-width:480px){:host{font-size:13px;--pad:15px}button,input,select{min-height:42px}dialog header{padding:15px}}`;
class Base extends HTMLElement{
 static get observedAttributes(){return['theme','accent','density','paused','reduced','speed','strength','text','seed','detail','variant','duration','label','count','radius','columns','start','placeholder','multiple','week-start','min','max'];}
 constructor(){super();this.attachShadow({mode:'open'});this.time=0;this.cleanups=[];this.visible=true;this.last=0;this._connected=false;}
 connectedCallback(){if(this._connected)return;this._connected=true;this.abort=new AbortController();this.media=matchMedia('(prefers-reduced-motion: reduce)');this.appearance();this._mounting=true;try{this.mount();}finally{this._mounting=false;}this.resize=new ResizeObserver(()=>this.resized?.());this.resize.observe(this);this.intersection=new IntersectionObserver(([entry])=>{this.visible=entry.isIntersecting;this.schedule();});this.intersection.observe(this);this.listen(document,'visibilitychange',()=>this.schedule());this.listen(this.media,'change',()=>this.schedule());this.schedule();}
 disconnectedCallback(){this._connected=false;this.abort?.abort();this.resize?.disconnect();this.intersection?.disconnect();cancelAnimationFrame(this.raf);for(const dispose of this.cleanups)dispose();this.cleanups=[];this.shadowRoot.getAnimations?.({subtree:true}).forEach(a=>a.cancel());this.teardown?.();}
 attributeChangedCallback(name,old,value){if(!this._connected||old===value)return;this.appearance();if(['paused','reduced'].includes(name))this.schedule();this.configured?.(name);}
 get color(){const c=this.getAttribute('accent');return /^#[a-f\d]{6}$/i.test(c||'')?c:'#c6e6b0';}
 get reduced(){return this.hasAttribute('reduced')||this.media?.matches;}
 get running(){return this._connected&&this.visible&&!document.hidden&&!this.hasAttribute('paused')&&!this.reduced;}
 appearance(){const accent=this.getAttribute('accent');this.style.setProperty('--accent',/^#[a-f\d]{6}$/i.test(accent||'')?accent:'#c6e6b0');}
 number(name,fallback,min=-Infinity,max=Infinity){const value=Number(this.getAttribute(name));return this.hasAttribute(name)&&Number.isFinite(value)?clamp(value,min,max):fallback;}
 text(name,fallback){return this.getAttribute(name)||fallback;}
 render(html,css=''){this.shadowRoot.innerHTML=`<style>${baseCSS}\n${css}</style>${html}`;this.$$('.panel').forEach(n=>n.setAttribute('part','surface'));this.$$('button').forEach(n=>{if(!n.hasAttribute('part'))n.setAttribute('part','button');});this.$$('input,select,textarea').forEach(n=>n.setAttribute('part','field'));}
 $(selector){return this.shadowRoot.querySelector(selector);}
 $$(selector){return[...this.shadowRoot.querySelectorAll(selector)];}
 listen(target,type,callback,options={}){target?.addEventListener(type,callback,{...options,signal:this.abort.signal});}
 emit(name,detail){return this.dispatchEvent(new CustomEvent(name,{detail,bubbles:true,composed:true}));}
 later(fn,delay){const dispose=()=>clearTimeout(id);const id=setTimeout(()=>{this.cleanups=this.cleanups.filter(item=>item!==dispose);if(this._connected)fn();},delay);this.cleanups.push(dispose);return id;}
 animate(fn){this.frame=fn;this.schedule();}
 schedule(){cancelAnimationFrame(this.raf);const motion=this.running;for(const a of this.shadowRoot.getAnimations?.({subtree:true})||[])motion?a.play():a.pause();this.style.setProperty('--play-state',motion?'running':'paused');this.last=0;if(this.frame){this.frame(0,this.time);if(motion)this.raf=requestAnimationFrame(timestamp=>this.tick(timestamp));}}
 tick(timestamp){if(!this.running)return;const dt=this.last?Math.min(.04,(timestamp-this.last)/1000):0;this.last=timestamp;this.time+=dt;this.frame?.(dt,this.time);this.raf=requestAnimationFrame(next=>this.tick(next));}
 tween(node,keyframes,options={}){if(this.reduced||!node.animate)return null;const animation=node.animate(keyframes,{duration:this.number('duration',500,100,1600),easing:'cubic-bezier(.22,.8,.2,1)',...options});const dispose=()=>animation.cancel();const release=()=>{this.cleanups=this.cleanups.filter(item=>item!==dispose);};animation.addEventListener('finish',release,{once:true});animation.addEventListener('cancel',release,{once:true});this.cleanups.push(dispose);return animation;}
 setupDialog(dialog,trigger){this.listen(trigger,'click',()=>{this.dialogTrigger=trigger;dialog.showModal();});this.listen(dialog,'click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});this.listen(dialog,'close',()=>this.dialogTrigger?.focus());}
}
class Vector extends Base {
 mount(){this.artId=uid();this.render(`<section class="vector-scene"><header><span class="label">VECTOR STUDY / EDITABLE GEOMETRY</span><h2>${escape(this.heading)}</h2><p class="hint">${escape(this.note||'A little geometry. A different point of view.')}</p></header><div class="art"></div><footer><span>LIVE VECTOR / NO EXTERNAL ASSETS</span><span class="measure"></span></footer></section>`,`.vector-scene{background:var(--bg);border:1px solid var(--line);border-radius:var(--radius);overflow:hidden}header{padding:28px 28px 0}h2{font:400 clamp(25px,4vw,36px) Georgia;margin:10px 0 9px;letter-spacing:-.8px}header p{font-size:11px}.art{width:100%;min-height:300px;touch-action:none}.art>svg{display:block;width:100%;height:auto;max-height:390px}.art [data-handle]{cursor:grab}.art [data-handle]:active{cursor:grabbing}footer{display:flex;justify-content:space-between;gap:12px;padding:14px 25px 18px;font-size:7px;letter-spacing:1px;color:var(--muted);border-top:1px solid var(--line)}@media(max-width:480px){header{padding:22px 20px 0}.art{min-height:245px}.art>svg{height:290px}footer{font-size:6px;padding:13px 18px;letter-spacing:.6px}}`);this.draw();const area=this.$('.art');this.listen(area,'pointerdown',event=>{const handle=event.target.closest('[data-handle]');if(!handle||!this.interact)return;this.drag=Number(handle.dataset.handle);area.setPointerCapture(event.pointerId);this.interact(this.drag,this.point(event),false);});this.listen(area,'pointermove',event=>{if(this.drag!==null&&this.drag!==undefined&&this.interact)this.interact(this.drag,this.point(event),false);else this.hover?.(this.point(event));});this.listen(area,'pointerup',()=>this.drag=null);this.listen(area,'pointercancel',()=>this.drag=null);this.listen(area,'keydown',event=>{const handle=event.target.closest('[data-handle]');if(!handle||!this.keyHandle)return;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Enter',' '].includes(event.key)){event.preventDefault();const id=Number(handle.dataset.handle);this.keyHandle(id,event.key,event.shiftKey);this.$(`[data-handle="${id}"]`)?.focus();}});}
 point(event){const r=this.$('svg').getBoundingClientRect(),scale=Math.min(r.width/720,r.height/420),left=r.left+(r.width-720*scale)/2,top=r.top+(r.height-420*scale)/2;return{x:clamp((event.clientX-left)/scale,0,720),y:clamp((event.clientY-top)/scale,0,420)};}
 configured(name){if(!['paused','reduced','theme','density'].includes(name))this.draw();}
 draw(){if(!this.$('.art'))return;this.$('.art').innerHTML=this.build();this.$('.measure').textContent=`${this.$$('svg path,svg polygon,svg circle,svg ellipse').length} VECTOR ELEMENTS`;this.emit('art-change',{seed:this.number('seed',1),frequency:this.number('strength',1)});}
 svg(content,description=''){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 720 420" width="720" height="420" role="img" aria-labelledby="${this.artId}-title ${this.artId}-desc"><title id="${this.artId}-title">${escape(this.heading)}</title><desc id="${this.artId}-desc">${escape(description||this.note||'Original parametric vector artwork.')}</desc>${content}</svg>`;}
 getSVG(){const svg=this.$('svg').cloneNode(true);svg.querySelectorAll('[tabindex],[role=button]').forEach(node=>{node.removeAttribute('tabindex');node.removeAttribute('role');node.removeAttribute('data-handle');});return new XMLSerializer().serializeToString(svg);}
}

for(const key of ['items','rows','options','commands','chapters'])Object.defineProperty(Base.prototype,key,{get(){return this['_'+key];},set(value){if(value!==null&&value!==undefined&&!Array.isArray(value))throw new TypeError(`${key} must be an array`);this['_'+key]=value;if(this._connected&&!this._mounting&&!this._rebuilding){this._rebuilding=true;this.disconnectedCallback();this.connectedCallback();this._rebuilding=false;}}});

function downloadBlob(data,name,type='application/octet-stream'){const url=URL.createObjectURL(new Blob([data],{type}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1200);}
